"""Strip Whisper JA ASR name / filler loops before MT.

Port of Transub desktop ``ja-person-names-core.stripAsrHallucinationLoops``:
consecutive CJK name stems (玲奈玲奈 / 葵葵葵) and whole-cue name debris
must not reach Opus or external MT.
"""

from __future__ import annotations

import re
from typing import Any

# Multi-char stems Whisper often loops on soft JA AV (validated on SNOS/FNS/CJOD).
_MULTI_LOOP_STEMS: tuple[str, ...] = (
    "玲奈",
    "莉奈",
    "佳奈",
    "纱奈",
    "沙奈",
    "真理",
    "理子",
    "绘真",
    "绘里",
    "美咲",
    "结衣",
    "阳菜",
    "春奈",
    "桃子",
    "琴音",
    "黄奈",
    "奏翔",
    "斗碧",
    "乃爱",
    "爱奈",
    "露娜",
    "环奈",
    "花音",
    "雏子",
    "真寻",
    "圣音",
    "明日香",
)

# Single-char / short filler loops (葵葵葵 / 嬉嬉嬉).
_SINGLE_LOOP_STEMS: tuple[str, ...] = (
    "葵",
    "嬉",
    "笑",
    "爱",
    "愛",
    "盐",
    "塩",
    "鸭",
    "鴨",
    "舞",
    "桃",
    "玲",
    "樱",
    "凛",
    "花",
    "月",
)

_HONORIFIC_RE = re.compile(r"(さん|くん|ちゃん|君|様|氏)")
_PUNCT_ONLY_RE = re.compile(r"^[…⋅・.\s。！？!?～〜ー\-'\"\u3000]*$")
_NAME_BARE_RE = re.compile(r"[…⋅・.。！？!?\s～〜\-ー'\"\u3000]+")


def _escape(tok: str) -> str:
    return re.escape(tok)


def _loop_tokens() -> list[str]:
    toks = list(_MULTI_LOOP_STEMS) + list(_SINGLE_LOOP_STEMS)
    # Longest first so 玲奈 wins over 玲
    toks.sort(key=lambda t: (-len(t), t))
    return toks


_LOOP_TOKENS = _loop_tokens()


def is_name_only_debris(text: str) -> bool:
    """True when cue is only a known pollution stem (+ punctuation)."""
    bare = _NAME_BARE_RE.sub("", str(text or "").strip())
    if not bare or len(bare) > 4:
        return False
    return bare in _MULTI_LOOP_STEMS or bare in _SINGLE_LOOP_STEMS


def strip_asr_name_loops(text: str) -> tuple[str, list[str]]:
    """
    Remove consecutive name/filler loops from one cue.

    Returns (cleaned_text, list_of_stripped_stems).
    """
    raw = str(text or "")
    cur = raw
    stripped: list[str] = []

    for tok in _LOOP_TOKENS:
        esc = _escape(tok)
        re_consec = re.compile(rf"(?:{esc}){{2,}}")
        if re_consec.search(cur):
            if tok not in stripped:
                stripped.append(tok)
            cur = re_consec.sub("", cur)
        re_ellipsis = re.compile(
            rf"(?:{esc})(?:\s*[…⋅・.。]{{1,6}}\s*(?:{esc}))+"
        )
        if re_ellipsis.search(cur):
            if tok not in stripped:
                stripped.append(tok)
            cur = re_ellipsis.sub("", cur)

    cur = re.sub(r"[^\S\n]{2,}", " ", cur).strip()

    if stripped:
        cur = re.sub(r"^[…⋅・.。～〜ー\s\-]+|[…⋅・.。～〜ー\s\-]+$", "", cur).strip()
        if _PUNCT_ONLY_RE.match(cur or ""):
            cur = ""

    # Whole-cue pollution name with no honorific (玲奈 / 玲奈…) → drop
    if is_name_only_debris(cur) and not _HONORIFIC_RE.search(raw):
        bare = _NAME_BARE_RE.sub("", cur)
        if bare and bare not in stripped:
            stripped.append(bare)
        cur = ""

    return cur, stripped


def strip_asr_name_loops_in_cues(
    cues: list[dict[str, Any]] | None,
    *,
    drop_empty: bool = True,
) -> tuple[list[dict[str, Any]], int]:
    """
    Rewrite cue texts in place (new dicts); optionally drop emptied cues.

    Returns (cues, changed_count).
    """
    if not cues:
        return [], 0
    out: list[dict[str, Any]] = []
    changed = 0
    for cue in cues:
        if not isinstance(cue, dict):
            continue
        text = str(cue.get("text") or "")
        cleaned, stripped = strip_asr_name_loops(text)
        if stripped or cleaned != text.strip():
            changed += 1
            cue = {**cue, "text": cleaned}
        if drop_empty and not str(cue.get("text") or "").strip():
            continue
        out.append(cue)
    return out, changed
